import { readFile, writeFile } from "node:fs/promises";

const source = new URL("./sample-dictionary.json", import.meta.url);
const destination = new URL(
  "../../../fallen-mobile/app/src/main/java/com/fallen/data/local/dictionary/SampleDictionary.kt",
  import.meta.url,
);
const manifest = JSON.parse(await readFile(source, "utf8"));
const literal = (value) => JSON.stringify(value).replaceAll("$", () => "\\$");
const words = manifest.words.filter((word) => word.active);
const lines = [
  "// Generated by fallEN/tools/dictionary/generate-android-sample.mjs.",
  "package com.fallen.data.local.dictionary",
  "",
  "import com.fallen.domain.model.Meaning",
  "import com.fallen.domain.model.Word",
  "",
  "internal object SampleDictionary {",
  `    const val releaseId = ${literal(manifest.releaseId)}`,
  "    val words = listOf(",
  ...words.flatMap((word) => [
    `        Word(${literal(word.wordId)}, ${word.version}, ${literal(word.spelling)}, ${literal(word.phonetic ?? "")}, listOf(`,
    ...word.meanings.map(
      (meaning) =>
        `            Meaning(${[meaning.id, meaning.partOfSpeech, meaning.text, meaning.example ?? "", meaning.exampleTranslation ?? ""].map(literal).join(", ")}),`,
    ),
    "        ), releaseId),",
  ]),
  "    )",
  "    val byId = words.associateBy(Word::id)",
  "    val aliases = mapOf(",
  ...words
    .filter((word) => word.otherSpellings.length)
    .map(
      (word) =>
        `        ${literal(word.wordId)} to listOf(${word.otherSpellings.map(literal).join(", ")}),`,
    ),
  "    )",
  "}",
  "",
].join("\n");

if (process.argv.includes("--check")) {
  const current = (await readFile(destination, "utf8")).replaceAll(
    "\r\n",
    "\n",
  );
  if (current !== lines)
    throw new Error(
      "Android sample is out of date. Run generate-android-sample.mjs.",
    );
} else await writeFile(destination, lines);
